const PRINT_CSS = String.raw`@charset "UTF-8";
:root{--orange:#EA580C;--ink:#151c21;--muted:#58636a;--line:#bbc4c7;--soft:#edf0ef;--font:Arial,Helvetica,sans-serif;--mono:"Liberation Mono",Consolas,monospace}
*{box-sizing:border-box}html,body{margin:0;color:var(--ink);font-family:var(--font);background:#e5e7e5}button,a,input{font:inherit}a{color:inherit}
.toolbar{max-width:1060px;margin:18px auto;display:flex;gap:10px;justify-content:space-between;align-items:center;padding:10px 16px;background:#141a1e;color:#fff;font-size:13px}.toolbar div{display:flex;gap:8px;flex-wrap:wrap}.toolbar a,.toolbar button{border:1px solid #424a4f;color:#fff;background:#222b30;padding:10px 15px;text-decoration:none;cursor:pointer}.toolbar button{background:var(--orange);border-color:var(--orange)}
.sheet{width:210mm;min-height:297mm;padding:12mm 13mm 14mm;margin:18px auto;background:white;position:relative;box-shadow:0 18px 40px #0003}.landscape .sheet{width:297mm;min-height:210mm;padding:10mm 12mm 11mm}
.doc-head{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:15px;border-bottom:3px solid var(--orange);padding-bottom:8mm}.brandline{font-size:23px;font-weight:900;letter-spacing:-.055em;line-height:1}.brandline b{color:var(--orange)}.brandline span{font-size:9px;font-weight:700;letter-spacing:.26em;display:block;margin-top:4px}.doc-id{text-align:right;font:700 9px/1.65 var(--mono);letter-spacing:.06em}.doc-id b{font-size:13px;color:var(--orange);display:block}
.doc-kicker{font:700 9px var(--mono);color:var(--orange);letter-spacing:.12em;margin:20px 0 7px;text-transform:uppercase}h1{font-size:29px;line-height:1.07;margin:0 0 7px;letter-spacing:-.05em;text-transform:uppercase}h2{font-size:13px;line-height:1.2;margin:17px 0 6px;text-transform:uppercase;letter-spacing:.025em;border-left:4px solid var(--orange);padding:3px 8px}p{font-size:10px;line-height:1.45;margin:6px 0 9px}small,.mini{font:700 8px/1.45 var(--mono);letter-spacing:.04em;color:var(--muted)}.subtitle{color:var(--muted);font-size:10px;line-height:1.5;max-width:110ch}
.meta-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--line);border-left:1px solid var(--line);margin:15px 0 18px}.meta{padding:7px 8px;min-height:42px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.meta small{display:block;text-transform:uppercase;font-size:7px}.meta strong{display:block;font-size:10px;margin-top:4px;line-height:1.25;overflow-wrap:anywhere}
.section-h{display:flex;justify-content:space-between;align-items:end;gap:10px;margin-top:14px;margin-bottom:6px;border-bottom:2px solid var(--ink);padding-bottom:6px}.section-h h2{border:0;margin:0;padding:0}.section-h small{text-align:right}
.grid{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9px;line-height:1.3}th{background:#e8eded;text-transform:uppercase;text-align:left;font:700 7px/1.25 var(--mono);letter-spacing:.035em;border:1px solid #a9b1b4;padding:8px 6px}td{border:1px solid #bbc3c7;padding:8px 6px;vertical-align:top;overflow-wrap:anywhere;height:30px}tbody tr:nth-child(even) td{background:#f9faf9}.num{text-align:right;font-variant-numeric:tabular-nums}.center{text-align:center}.pill{display:inline-block;border:1px solid #819096;background:#fff;color:#4c5a60;padding:4px 7px;font:700 8px var(--mono)}.pending{color:#8a5908;background:#fff8e9;border-color:#d5b57d}
.panels{display:grid;grid-template-columns:1fr 1fr;gap:8px}.panel{border:1px solid var(--line);padding:11px 12px;min-height:75px;background:#fbfcfb}.panel small{display:block;text-transform:uppercase}.panel strong{display:block;font-size:11px;margin:7px 0;line-height:1.35}.panel p{margin:0;font-size:9px;color:#4b555c}.note{border-left:4px solid var(--orange);background:#f1f3f2;padding:9px 11px;margin-top:12px;color:#333e44;font-size:9px;line-height:1.48}.notes-lines{min-height:75px;background:repeating-linear-gradient(transparent 0 20px,#cfd5d7 21px,transparent 22px)}.signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px}.signature{border-top:1px solid #707b81;padding-top:6px;font:700 8px var(--mono);min-height:30px}.footer{display:flex;justify-content:space-between;gap:10px;border-top:1px solid var(--line);margin-top:16px;padding-top:7px;font:700 7px var(--mono);color:#647178}.footer span:last-child{text-align:right}
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0}.step{border:1px solid var(--line);padding:10px 10px 14px}.step .n{font:900 19px var(--mono);color:var(--orange)}.step strong{display:block;font-size:11px;margin-top:6px}.step p{color:#5a646a;font-size:9px}.checklist{list-style:none;padding:0;margin:4px 0;display:grid;gap:8px}.checklist li{font-size:10px;border-bottom:1px solid #c4c9cb;min-height:25px;padding-bottom:4px}.checklist li:before{content:'☐';font-size:15px;margin-right:9px;color:#515b60}
.status-strip{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;background:#151c20;color:#fff;font:700 10px var(--mono);margin-top:12px}.status-strip b{color:#ff8139}.caution{color:#81491c}
@media screen and (max-width:1100px){.sheet{transform-origin:top center;max-width:100%;width:min(210mm,100%);min-height:auto}.landscape .sheet{max-width:none}.toolbar{margin:0 0 12px}}
@page{size:A4 portrait;margin:0}
@media print{html,body{background:#fff!important}.toolbar{display:none!important}.sheet{box-shadow:none;margin:0;width:210mm;min-height:297mm;padding:12mm 13mm 13mm;break-after:page;page-break-after:always}.landscape .sheet{width:297mm;min-height:210mm;padding:10mm 12mm}.sheet:last-child{break-after:auto;page-break-after:auto}.sheet,.doc-head,.meta-grid,.panel,table{print-color-adjust:exact;-webkit-print-color-adjust:exact}thead{display:table-header-group}tr,.panel,.steps{break-inside:avoid;page-break-inside:avoid}a{text-decoration:none}}

/* one-sheet A4 optimizations for blank shop-floor templates */
.landscape .sheet{padding-top:8mm;padding-bottom:8mm}
.landscape .doc-head{padding-bottom:4mm}
.landscape .doc-kicker{margin:11px 0 4px}
.landscape h1{font-size:25px;margin-bottom:4px}
.landscape .meta-grid{margin:9px 0 9px}
.landscape .meta{min-height:30px;padding:5px 7px}
.landscape .meta small{font-size:6.7px}
.landscape .meta strong{font-size:9px;margin-top:2px}
.landscape .section-h{margin-top:9px;margin-bottom:4px;padding-bottom:4px}
.landscape td{padding:4px 6px;height:21px;font-size:8px}
.landscape th{padding:5px 6px}
.landscape .panel{min-height:55px;padding:8px}
.landscape .note{padding:6px 9px;margin-top:8px}
.landscape .signatures{margin-top:12px}
.doc-traveler .meta{min-height:34px;padding:5px 7px}
.doc-traveler .meta-grid{margin:9px 0 11px}
.doc-traveler .doc-head{padding-bottom:5mm}
.doc-traveler .doc-kicker{margin-top:11px}
.doc-traveler .section-h{margin-top:9px;margin-bottom:5px;padding-bottom:4px}
.doc-traveler td{height:24px;padding:4px 6px}
.doc-traveler th{padding:6px}
.doc-traveler .panel{min-height:50px;padding:7px}
.doc-traveler .checklist{gap:3px}
.doc-traveler .checklist li{min-height:20px;font-size:9px}
.doc-traveler .notes-lines{min-height:38px}
.doc-traveler .signatures{margin-top:12px}
.doc-traveler .footer{margin-top:8px}
@media print{
 .landscape .sheet{padding:8mm 12mm}
}

.official-brand{display:block;width:47mm;max-width:100%;height:auto;object-fit:contain;object-position:left center;margin:0}
`;
'use strict';
const TYPES={
 fai:{label:'FAI / FØRSTEEMNEKONTROL',abbr:'FAI',columns:[['number','#'],['feature','Karakteristik'],['nominal','Nominel'],['low','Nedre grænse'],['high','Øvre grænse'],['actual','Målt'],['instrument','Instrument']],measured:true},
 setup:{label:'CNC / SETUP SHEET',abbr:'SETUP',columns:[['number','T# / OP'],['feature','Værktøj / aktivitet'],['nominal','Ø / WCS'],['low','Udhæng'],['high','Offset / program'],['actual','Kontrolpunkt'],['instrument','Status']]},
 process:{label:'PROCESARK',abbr:'PROC',columns:[['number','OP'],['feature','Proces / aktivitet'],['nominal','Maskine'],['low','Værktøj / metode'],['high','Kontrolpunkt'],['actual','Tid / dato'],['instrument','Signatur']]},
 inspection:{label:'KONTROLARK',abbr:'INSP',columns:[['number','#'],['feature','Mål / egenskab'],['nominal','Nominel'],['low','Min.'],['high','Maks.'],['actual','Målt'],['instrument','Instrument']],measured:true},
 traveler:{label:'JOB TRAVELER',abbr:'TRAV',columns:[['number','OP'],['feature','Afdeling / maskine'],['nominal','Arbejde'],['low','Antal ind'],['high','Antal ud'],['actual','Dato'],['instrument','Signatur']]}
};
const PRESETS={
 'flame-eater':{project:'Flame Eater',part:'',material:'',machine:'',description:'Komponent fra Flame Eater-projektet. Udfyld konkret emne og tegningsrevision før frigivelse.'},
 'ring-bender':{project:'Ring Bender',part:'',material:'',machine:'',description:'Specialværktøj med drejning/fræsning. Verificér de konkrete projektoplysninger.'},
 'tac-table':{project:'Tac Table',part:'Tac Table',material:'EN AW-6082-T6',machine:'Haas Mini Mill',description:'CNC-fræsning med fokus på opspænding, planhed og operationsrækkefølge. Verificér mod projektets tegninger.'}
};
const fields=['project','part','docId','rev','drawing','material','machine','date','operator','reviewer','wcs','program','description','notes'];
const newRow=(n)=>({number:String(n),feature:'',nominal:'',low:'',high:'',actual:'',instrument:''});
let documentType='fai';let rows=[newRow(1),newRow(2),newRow(3),newRow(4)];
const form=document.querySelector('#document-form');const editor=document.querySelector('#record-editor');const preview=document.querySelector('#preview');const msg=document.querySelector('#live-status');
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function get(name){return form.elements.namedItem(name)?.value?.trim()??'';}
function set(name,v){const e=form.elements.namedItem(name);if(e)e.value=v??'';}
function showMessage(s){msg.textContent=s;}
function parseNumber(str){if(!String(str??'').trim())return null;const normalized=String(str).replaceAll(' ','').replace(',','.');if(!/^[+-]?(\d+\.?\d*|\.\d+)$/.test(normalized))return NaN;return Number(normalized);}
function getMeasureStatus(row){
 const n=['low','high','actual'].map(k=>parseNumber(row[k]));
 if(n.some(v=>v===null))return 'AFVENTER';
 if(n.some(v=>!Number.isFinite(v)))return 'UGYLDIG';
 if(n[0]>n[1])return 'UGYLDIG';
 return n[2]>=n[0]&&n[2]<=n[1]?'INDENFOR':'AFVIGELSE';
}
function release(){
 if(!TYPES[documentType].measured)return 'KLADDE / IKKE FRIGIVET';
 const statuses=rows.map(getMeasureStatus);
 // Never hide an out-of-tolerance measurement behind missing metadata.
 if(statuses.includes('AFVIGELSE'))return 'AFVIGELSE / HOLD';
 if(statuses.includes('UGYLDIG'))return 'UGYLDIGT MÅLEGRUNDLAG';
 if(rows.length===0||rows.some(r=>!r.feature.trim()||parseNumber(r.nominal)===null||!Number.isFinite(parseNumber(r.nominal))||!r.instrument.trim())||!get('project')||!get('part')||!get('drawing'))return 'AFVENTER / UFULDDATA';
 if(statuses.some(s=>s!=='INDENFOR'))return 'AFVENTER / UFULDDATA';
 if(!form.elements.namedItem('reviewed').checked||!get('reviewer'))return 'INDENFOR / AFVENTER FRIGIVELSE';
 return 'GENNEMGÅET / AFVENTER SIGNATUR';
}
function updateType(t){if(!TYPES[t])return;documentType=t;rows=Array.from({length:4},(_,i)=>newRow(i+1));form.elements.namedItem('reviewed').checked=false;document.querySelectorAll('[data-type]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.type===t)));document.querySelector('#records-label').textContent=TYPES[t].measured?'Målekarakteristikker':'Arbejdsrækker';set('docId','D-'+TYPES[t].abbr+'-DRAFT');drawRows();updatePreview();}
function drawRows(){const col=TYPES[documentType].columns;editor.replaceChildren();rows.forEach((row,i)=>{const card=document.createElement('div');card.className='row-card';const h=document.createElement('div');h.className='row-card-head';h.innerHTML='<strong>RÆKKE '+String(i+1).padStart(2,'0')+'</strong><button type="button" aria-label="Fjern række '+(i+1)+'">FJERN ×</button>';h.querySelector('button').addEventListener('click',()=>{rows.splice(i,1);drawRows();updatePreview()});card.append(h);const grid=document.createElement('div');grid.className='fields';col.forEach(([key,label])=>{const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type='text';input.value=row[key]||'';input.dataset.key=key;input.addEventListener('input',()=>{rows[i][key]=input.value;updatePreview()});wrap.append(input);grid.append(wrap)});card.append(grid);editor.append(card)});}
function collect(){const d={schema:'datum-v4.0',type:documentType,rows:rows.map(r=>({...r})),reviewed:!!form.elements.namedItem('reviewed').checked};fields.forEach(f=>d[f]=get(f));return d;}
function load(d){if(!d||typeof d!=='object'||d.schema!=='datum-v4.0'||!TYPES[d.type]||!Array.isArray(d.rows)||d.rows.length>150)throw Error('Ugyldigt Datum-dokument eller for mange rækker');updateType(d.type);fields.forEach(f=>set(f,typeof d[f]==='string'?d[f].slice(0,2000):''));rows=d.rows.map((r,i)=>{const o=newRow(i+1);Object.keys(o).forEach(k=>o[k]=typeof r[k]==='string'?r[k].slice(0,1000):'');return o});form.elements.namedItem('reviewed').checked=Boolean(d.reviewed);drawRows();updatePreview();}
function metaEntry(k,v){return `<div class="meta"><small>${esc(k)}</small><strong>${esc(v||'—')}</strong></div>`;}
function makeHtml(){
 const d=collect(), t=TYPES[d.type], isSetup=d.type==='setup';
 const state=release();
 const tableCols=[...t.columns.map(v=>v[1]),...(t.measured?['Afvigelse','Resultat']:[])];
 let tableRows=rows.map((row,i)=>{
  const vals=t.columns.map(([k])=>row[k]||'—');if(t.measured){const actual=parseNumber(row.actual),nominal=parseNumber(row.nominal);const deviation=actual!==null&&nominal!==null&&Number.isFinite(actual)&&Number.isFinite(nominal)?actual-nominal:null;vals.push(deviation===null?'—':(deviation>=0?'+':'')+deviation.toFixed(3).replace('.',','));vals.push(getMeasureStatus(row));}
  return '<tr>'+vals.map((v,j)=>`<td${j===0?' class="center"':''}>${esc(v)}</td>`).join('')+'</tr>';
 }).join('');
 if(!tableRows){tableRows='<tr><td colspan="'+tableCols.length+'">Ingen rækker endnu</td></tr>';}
 const meta=[['Projekt / ordre',d.project],['Emne / del',d.part],['Tegning / revision',d.drawing],['Materiale',d.material],['Maskine',d.machine],['Dato',d.date],['Operatør',d.operator],['Kontrolleret af',d.reviewer]];
 const header=`<header class="doc-head"><img class="official-brand" src="data:image/png;base64," alt="Datum Prototyping"><div class="doc-id">DOKUMENT / ${esc(t.abbr)}<b>${esc(d.docId||'D-'+t.abbr+'-DRAFT')}</b>REV: ${esc(d.rev||'KLADDE')} &nbsp; · &nbsp; V4.0</div></header>`;
 const caption=d.type==='fai'||d.type==='inspection'?'Måling og kontrolresultat':'Arbejdsgrundlag / procesplan';
 const extras= d.type==='setup'?`<div class="panels"><div class="panel"><small>WCS / SETUP</small><strong>${esc(d.wcs||'Afventer')}</strong></div><div class="panel"><small>NC-PROGRAM</small><strong>${esc(d.program||'Afventer')}</strong></div></div>`:'';
 const sign=`<div class="signatures"><div class="signature">Operatør / dato</div><div class="signature">Kontrolleret / dato</div><div class="signature">Frigivet / dato</div></div>`;
 const body=`${header}<p class="doc-kicker">DATUM / PRODUKTIONSDOKUMENT / ${esc(t.abbr)}</p><h1>${esc(t.label)}</h1><p class="subtitle">${esc(d.description||'Udfyld relevant proces- eller kontrolgrundlag før anvendelse.')}</p><section class="meta-grid">${meta.map(([k,v])=>metaEntry(k,v)).join('')}</section>${extras}<div class="section-h"><h2>${esc(caption)}</h2><small>${t.measured?'Faktiske mål skal verificeres; ingen automatisk frigivelse':'Angiv operationer og ansvarlig før udførelse'}</small></div><table class="grid"><thead><tr>${tableCols.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>${tableRows}</tbody></table><div class="status-strip"><span>STATUS / DISPOSITION</span><b>${esc(state)}</b></div><h2>Bemærkninger / afvigelser</h2><p>${esc(d.notes||'Ingen bemærkninger registreret. Verificér alle oplysninger før brug.')}</p>${sign}<div class="footer"><span>DATUM PROTOTYPING · DOCUMENT STUDIO V4.0</span><span>${esc(d.docId||'KLADDE')} · ${esc(d.rev||'KLADDE')} · ${esc(d.project||'PROJEKT MANGLER')}</span></div>`;
 return `<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(d.docId||t.label)} · Datum Prototyping</title><style>${PRINT_CSS}</style>${isSetup?'<style>@page{size:A4 landscape;margin:0}</style>':''}</head><body class="${isSetup?'landscape':'portrait'}"><main class="sheet">${body}</main></body></html>`;
}
let timer=null;
function updatePreview(){clearTimeout(timer);timer=setTimeout(()=>{preview.srcdoc=makeHtml();showMessage('STATUS: '+release())},120)}
function download(content,mime,filename){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function safeName(s){return String(s).toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/-+/g,'-').slice(0,50)||'kladd';}
document.querySelectorAll('[data-type]').forEach(el=>el.addEventListener('click',()=>updateType(el.dataset.type)));
document.querySelector('#add-row').addEventListener('click',()=>{rows.push(newRow(rows.length+1));drawRows();updatePreview()});
form.addEventListener('input',updatePreview);form.addEventListener('change',updatePreview);
document.querySelector('#project-preset').addEventListener('change',e=>{const p=PRESETS[e.target.value];if(p){['project','part','material','machine','description'].forEach(k=>set(k,p[k]));form.elements.namedItem('reviewed').checked=false;}updatePreview()});
document.querySelector('#export-json').addEventListener('click',()=>download(JSON.stringify(collect(),null,2),'application/json;charset=utf-8',safeName(get('project'))+'-'+documentType+'.json'));
document.querySelector('#export-html').addEventListener('click',()=>download(makeHtml(),'text/html;charset=utf-8',safeName(get('project'))+'-'+documentType+'.html'));
document.querySelector('#save-local').addEventListener('click',()=>{try{localStorage.setItem('datum-v4-document',JSON.stringify(collect()));showMessage('Kladden er gemt lokalt i denne browser.')}catch(e){showMessage('Lokal lagring er ikke tilgængelig. Brug eksportér data.')}});
document.querySelector('#import-json').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Fil over 1 MB');load(JSON.parse(await file.text()));showMessage('Data importeret – gennemgå alle felter før brug.')}catch(err){showMessage('Importfejl: '+err.message)}e.target.value=''});
document.querySelector('#reset-form').addEventListener('click',()=>{if(confirm('Nulstil dokumentet? Ueksporterede data forsvinder.')){form.reset();updateType('fai');showMessage('Dokument nulstillet.')}});
document.querySelector('#print-document').addEventListener('click',()=>{const frame=preview.contentWindow;frame?.focus();frame?.print()});
updateType('fai');{const project=new URLSearchParams(location.search).get('project');if(PRESETS[project]){const sel=document.querySelector('#project-preset');sel.value=project;sel.dispatchEvent(new Event('change'));}}try{const saved=localStorage.getItem('datum-v4-document');if(saved){load(JSON.parse(saved));showMessage('Gemt kladde genskabt fra denne browser.')}}catch(_){/* invalid local draft is ignored */}
